// KV store：内存键值存储（支持可选 TTL 过期）
const data = new Map();

// set(key, value, ttlMs?)：ttlMs 省略/为 null 表示永不过期
export function set(key, value, ttlMs) {
  const entry = { value };
  if (ttlMs !== undefined && ttlMs !== null) {
    entry.expiresAt = Date.now() + ttlMs;
  }
  data.set(key, entry);
}

export function get(key) {
  const entry = data.get(key);
  if (!entry) return undefined;
  if (entry.expiresAt !== undefined && Date.now() >= entry.expiresAt) {
    data.delete(key); // 惰性过期：读取时清理，避免残留占用
    return undefined;
  }
  return entry.value;
}

// 会话缓存层：使用 store 的 TTL 能力（会话 1 秒过期）
import { set as storeSet, get as storeGet } from './store.mjs';

const SESSION_TTL_MS = 1000;

export function cacheSession(sessionId, payload) {
  storeSet('session:' + sessionId, payload, SESSION_TTL_MS);
}

export function getCachedSession(sessionId) {
  return storeGet('session:' + sessionId);
}

